package com.agriconnect.order;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import java.math.*;import java.time.*;import java.util.*;import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;
class OrderWorkflowTest{private JdbcTemplate j;private OrderController orders;private CropInventoryClient crop;@BeforeEach void setup(){JdbcDataSource ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:orders;MODE=PostgreSQL;DB_CLOSE_DELAY=-1");j=new JdbcTemplate(ds);j.execute("drop all objects");j.execute("create table orders(id bigint generated by default as identity primary key,buyer_id bigint,total_amount numeric,status varchar(20),delivery_address varchar(255),order_date timestamp with time zone default current_timestamp,created_at timestamp with time zone default current_timestamp,return_state varchar(30))");j.execute("create table order_items(id bigint generated by default as identity primary key,order_id bigint,batch_id bigint,farmer_id bigint,inventory_reservation_id uuid,quantity numeric,unit_price numeric,subtotal numeric)");j.execute("create table crop_locks(id bigint generated by default as identity primary key,inventory_reservation_id uuid,batch_id bigint,buyer_id bigint,quantity numeric,status varchar(20),locked_at timestamp with time zone default current_timestamp,expired_at timestamp with time zone)");j.execute("create table idempotency_records(id bigint generated by default as identity primary key,idempotency_key varchar(200),command varchar(100),user_id bigint,request_hash varchar(64),response_status int,response_body varchar(255),state varchar(20),created_at timestamp with time zone default current_timestamp,unique(idempotency_key,command,user_id))");j.execute("create table order_status_history(id bigint generated by default as identity primary key,order_id bigint,from_status varchar(20),to_status varchar(20),changed_by bigint,changed_at timestamp with time zone default current_timestamp)");crop=mock(CropInventoryClient.class);orders=new OrderController(JdbcClient.create(ds),crop);auth(20);}@AfterEach void clear(){SecurityContextHolder.clearContext();}
@Test void duplicateCheckoutCreatesOneOrder(){UUID r=UUID.randomUUID();j.update("insert into crop_locks(inventory_reservation_id,batch_id,buyer_id,quantity,status,expired_at)values(?,?,?,?,?,?)",r,65,20,new BigDecimal("10"),"ACTIVE",OffsetDateTime.now().plusMinutes(10));when(crop.batch(65)).thenReturn(Map.of("farmerId",7));when(crop.commit(r)).thenReturn(Map.of("status","COMMITTED"));Map<String,Object>body=Map.of("totalAmount",100,"deliveryAddress","Address","cropLockIds",List.of(1),"items",List.of(Map.of("batchId",65,"quantity",10,"unitPrice",10)));orders.checkout("same-key",body);orders.checkout("same-key",body);assertThat(j.queryForObject("select count(*) from orders",Integer.class)).isEqualTo(1);verify(crop,times(1)).commit(r);}
@Test void rejectsInvalidTransition(){j.update("insert into orders(buyer_id,total_amount,status)values(20,0,'PENDING')");assertThatThrownBy(()->orders.status(1,Map.of("status","DELIVERED"))).isInstanceOfSatisfying(DomainException.class,e->assertThat(e.code).isEqualTo("INVALID_ORDER_STATUS_TRANSITION"));}private void auth(long id){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(String.valueOf(id),null,List.of()));}}
